insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 1, 'Quien es misericordioso, da prestado a su prójimo; y el que tiene abierta la mano para dar, observa los mandamientos del Señor.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 2, 'Préstale a tu prójimo en tiempo de su necesidad; y tú, a su tiempo, restituye lo que él te ha prestado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 3, 'Cumple tu palabra, y pórtate fielmente con él; y en todo tiempo hallarás lo que necesites.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 4, 'El dinero prestado lo consideraron muchos como un hallazgo');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 5, 'Hasta tanto que han recibido, besan las manos del que puede dar, y con voz humilde hacen grandes promesas;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 6, 'mas cuando es tiempo de pagar piden espera, y dicen cosas pesadas, y murmuran; y echan la culpa al tiempo.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 7, 'Y aunque se hallen en estado de pagar, pondrán dificultades; apenas volverán la mitad de la deuda, y el acreedor deberá hacer cuenta que aquello es como si se lo hubiese hallado.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 8, 'Y no siendo así lo defraudarán de su dinero; y sin más ni más se ganará el acreedor un enemigo,');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 9, 'el cual le pagará con injurias y maldiciones, y por un honor y un beneficio recibido le volverá ultrajes.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 10, 'Muchos dejan de prestar, no por dureza de corazón, sino por temor de ser burlados injustamente;');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 11, 'sin embargo, sé tú de alma más generosa con el humilde, y no le hagas esperar días y más días por la limosna.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 12, 'En cumplimiento del mandamiento de Dios socorre al pobre, y en su necesidad no lo despidas con las manos vacías.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 13, 'Pierde o gasta el dinero por amor de tu hermano y de tu amigo, y no lo escondas debajo de una losa para que se pierda, y con él tu alma.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 14, 'Emplea tu tesoro según los preceptos del Altísimo, y eso te valdrá más que el oro.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 15, 'Mete la limosna en el seno del pobre, y ella rogará por ti para librarte de toda suerte de males.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 18, 'Peleará contra tu enemigo harto mejor que el escudo y la lanza de un campeón.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 19, 'El hombre de bien da fianza por su prójimo; mas el que ha perdido el rubor, lo abandona a su suerte.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 20, 'No te olvides del beneficio que te ha hecho tu fiador, pues ha expuesto por ti su hacienda y aun quizá su vida.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 21, 'El pecador y el inmundo o infiel huyen del que ha sido fiador de ellos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 22, 'El pecador hace cuenta que son suyos los bienes del que ha dado fianza por él, y con corazón ingrato abandona a su libertador.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 23, 'Sale uno por fiador de su prójimo; y éste, perdida toda vergüenza, lo abandona.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 24, 'Fianzas indiscretas han perdido a muchos que lo pasaban bien, y los han sumergido en un mar de trabajos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 25, 'Ellas son las que trastornando a los hombres acaudalados los han hecho trasmigrar y andar errantes entre gentes extrañas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 26, 'El pecador que traspasa los mandamientos del Señor, se enredará en fianzas ruinosas; y el que se mete a tratar muchos negocios, no se verá libre de pleitos.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 27, 'Sostén al prójimo según tu posibilidad; pero mira también por ti mismo, a fin de que no te precipites.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 28, 'Lo esencial de la vida del hombre es agua y pan, y vestido y casa para tener cubierto aquello que no debe dejarse ver.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 29, 'Mejor es la comida del pobre, al abrigo de una choza, que banquetes espléndidos en tierra extraña donde no se tiene domicilio.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 30, 'Conténtate con lo que tuvieres, sea poco o mucho, y no tendrás que sentir los improperios que se hacen a los forasteros.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 31, 'Es una vida infeliz la del que va hospedándose de casa en casa; pues dondequiera que se hospede, no obrará con libertad, ni abrirá su boca.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 32, 'Lo hospedará uno el cual se quejará de que da de comer y beber a ingratos; y tras esto oirá otras cosas que lo amarguen.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 33, 'Vamos, le dirán al hospedado, por la mesa, y da de comer a los otros con lo que tienes a mano, o en tus alforjas.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 34, 'O bien, vete afuera, que vienen unos amigos míos de distinción, y necesito mi casa; o he de alojar a un hermano mío.');
insert into bible_verses_es (book_slug, chapter_num, verse_num, text) values ('ecclesiasticus', 29, 35, 'Para un hombre sensato dos cosas son muy pesadas, los desprecios que recibe del patrón de la casa, y los improperios del que le ha hecho el préstamo, cuando tarda en recobrarlo.');
